// Reset forces for the current particle range
for (size_t i = start; i < end; ++i) {
    particles[i].force = glm::vec3(0.0f);
}

// Iterate over each particle in the range
for (size_t i = start; i < end; ++i) {
    Particle& pi = particles[i];
    glm::vec3 pressureForce(0.0f);
    glm::vec3 viscosityForce(0.0f);

    // Get the cell of the current particle
    glm::ivec3 cell = getCell(&pi, h);
    // Check neighboring cells (including current cell)
    for (int x = -1; x <= 1; ++x) {
        for (int y = -1; y <= 1; ++y) {
            for (int z = -1; z <= 1; ++z) {
                glm::ivec3 neighborCell = cell + glm::ivec3(x, y, z);
                uint32_t hash = getHash(neighborCell);

                // Get the start index of particles in this cell
                uint32_t startIndex = particleTable[hash];
                if (startIndex == NO_PARTICLE) continue;

                // Iterate through particles in this cell
                uint32_t particleIndex = startIndex;
                while (particleIndex != NO_PARTICLE && particleIndex < particleCount) {
                    Particle& pj = particles[particleIndex];

                    // Skip self
                    if (&pi == &pj) {
                        particleIndex = pj.next;
                        continue;
                    }

                    // Calculate vector from pj to pi and distance
                    glm::vec3 rij = pi.position - pj.position;
                    float r2 = glm::dot(rij, rij);

                    // Only consider particles within smoothing radius
                    if (r2 < h2 && r2 > 0.0f) {
                        float r = std::sqrt(r2);
                        glm::vec3 rij_norm = rij / r;

                        // Pressure force calculation
                        float pressureTerm = -mass * (pi.pressure + pj.pressure) / (2.0f * pj.density);
                        pressureForce += pressureTerm * spikyGrad * std::pow(h - r, 2.0f) * rij_norm;

                        // Viscosity force calculation
                        viscosityForce += viscosity * mass * (pj.velocity - pi.velocity) / pj.density * spikyLap * (h - r);
                    }

                    particleIndex = pj.next;
                }
            }
        }
    }

    // Apply forces
    pi.force += pressureForce + viscosityForce;
    // Add gravity
    pi.force += glm::vec3(0.0f, -9.81f * pi.density * mass, 0.0f);
}

